import java.util.*;

public class Solution {
    static Map<Integer, Integer> counts = new HashMap<>();
    static int currentF = 0;

    public static int arrayAndQueries(int n, int[] A, int[][] queries) {
        int MOD = 1000000007;

        for (int v : A) {
            counts.put(v, counts.getOrDefault(v, 0) + 1);
        }

        for (int v : counts.keySet()) {
            currentF += getContribution(v);
        }

        long totalAns = 0;

        for (int i = 0; i < queries.length; i++) {
            int idx = queries[i][0] - 1;
            int newVal = queries[i][1];
            int oldVal = A[idx];

            Set<Integer> affected = new HashSet<>(Arrays.asList(oldVal, oldVal + 1, newVal, newVal + 1));

            for (int v : affected) {
                currentF -= getContribution(v);
            }

            counts.put(oldVal, counts.get(oldVal) - 1);
            if (counts.get(oldVal) == 0) counts.remove(oldVal);

            counts.put(newVal, counts.getOrDefault(newVal, 0) + 1);

            A[idx] = newVal;

            for (int v : affected) {
                currentF += getContribution(v);
            }

            long term = ((long)(i + 1) * (currentF % MOD)) % MOD;
            totalAns = (totalAns + term) % MOD;
        }

        return (int) totalAns;
    }

    private static int getContribution(int v) {
        int cv = counts.getOrDefault(v, 0);
        int cvPrev = counts.getOrDefault(v - 1, 0);
        return Math.max(0, cv - cvPrev);
    }
}
